// PRIMARY: beacon_node/beacon_chain/src/kzg_utils.rs:validate_data_columns (lines 49-96)
pub fn validate_data_columns<'a, E: EthSpec, I>(kzg: &Kzg, data_column_iter: I) -> Result<(), (Option<u64>, KzgError)>
where I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone {
    let mut cells = Vec::new();
    let mut proofs = Vec::new();
    let mut column_indices = Vec::new();
    let mut commitments = Vec::new();
    for data_column in data_column_iter {
        let col_index = data_column.index;
        if data_column.column.is_empty() {
            return Err((Some(col_index), KzgError::KzgVerificationFailed));
        }
        for cell in &data_column.column {
            cells.push(ssz_cell_to_crypto_cell::<E>(cell)...);
            column_indices.push(col_index);
        }
        for &proof in &data_column.kzg_proofs { proofs.push(Bytes48::from(proof)); }
        for &commitment in &data_column.kzg_commitments { commitments.push(Bytes48::from(commitment)); }
        // Array length consistency check per column
        if cells.len() != expected_len || proofs.len() != expected_len || commitments.len() != expected_len {
            return Err((Some(col_index), KzgError::InconsistentArrayLength(...)));
        }
    }
    kzg.verify_cell_proof_batch(&cells, &proofs, column_indices, &commitments)
}

