// PRIMARY: beacon_node/beacon_chain/src/kzg_utils.rs:reconstruct_data_columns (lines 366-411)
pub fn reconstruct_data_columns<E: EthSpec>(kzg: &Kzg, mut data_columns: Vec<Arc<DataColumnSidecar<E>>>, spec: &ChainSpec) -> Result<DataColumnSidecarList<E>, KzgError> {
    data_columns.sort_unstable_by_key(|dc| dc.index);  // Sorts for ascending order
    let first_data_column = data_columns.first().ok_or(...)?;
    let num_of_blobs = first_data_column.kzg_commitments.len();
    let blob_cells_and_proofs_vec = (0..num_of_blobs).into_par_iter().map(|row_index| {
        let mut cells = vec![];
        let mut cell_ids = vec![];
        for data_column in &data_columns {
            cells.push(ssz_cell_to_crypto_cell::<E>(...));
            cell_ids.push(data_column.index);
        }
        kzg.recover_cells_and_compute_kzg_proofs(&cell_ids, &cells)
    }).collect::<Result<...>>()?;
    // NOTE: No post-recovery KZG verification against original commitment here
    build_data_column_sidecars(...)
}

// CALLEE: crypto/kzg/src/lib.rs:recover_cells_and_compute_kzg_proofs (lines 318-331)
pub fn recover_cells_and_compute_kzg_proofs(self, cell_ids, cells) -> Result<CellsAndKzgProofs, Error> {
    let (cells, proofs) = self.context().recover_cells_and_kzg_proofs(cell_ids.to_vec(), cells.to_vec()).map_err(Error::PeerDASKZG)?;
    let c_kzg_proof = proofs.map(KzgProof);
    Ok((cells, c_kzg_proof))
}

